/* Bank soal. t = id materi. o = pilihan. a = nomor jawaban benar (mulai dari 0). e = pembahasan.
   lv: 1 mudah, 2 sedang, 3 sulit. src: "contoh" (bawaan) atau "pola" (dibuat dari pola soal yang kamu kirim).
   Soal di bawah ini contoh bawaan agar fitur kuis bisa dicoba. */
window.RB = window.RB || {};
RB.questions = [
  /* mat1 */
  { id: 'mat1-01', t: 'mat1', lv: 1, src: 'contoh', q: 'Akar-akar dari x² − 7x + 12 = 0 adalah …', o: ['3 dan 4', '2 dan 6', '−3 dan −4', '1 dan 12'], a: 0, e: 'Cari dua bilangan yang jumlahnya 7 dan hasil kalinya 12, yaitu 3 dan 4. Maka (x − 3)(x − 4) = 0.' },
  { id: 'mat1-02', t: 'mat1', lv: 1, src: 'contoh', q: 'Diskriminan dari 3x² − 2x + 1 = 0 adalah …', o: ['−8', '8', '16', '−16'], a: 0, e: 'D = b² − 4ac = (−2)² − 4·3·1 = 4 − 12 = −8.' },
  { id: 'mat1-03', t: 'mat1', lv: 1, src: 'contoh', q: 'Jumlah akar-akar dari 2x² − 10x + 7 = 0 adalah …', o: ['5', '−5', '7/2', '10'], a: 0, e: 'Jumlah akar = −b/a = 10/2 = 5. Angka 7/2 adalah hasil kali akar.' },
  { id: 'mat1-04', t: 'mat1', lv: 2, src: 'contoh', q: 'Titik puncak parabola y = x² − 6x + 5 adalah …', o: ['(3, −4)', '(−3, −4)', '(3, 4)', '(6, 5)'], a: 0, e: 'x = −b/2a = 6/2 = 3. Lalu y = 9 − 18 + 5 = −4.' },
  { id: 'mat1-05', t: 'mat1', lv: 2, src: 'contoh', q: 'Persamaan x² + kx + 9 = 0 punya akar kembar. Nilai k yang mungkin adalah …', o: ['6 atau −6', '3 atau −3', '6 saja', '9 atau −9'], a: 0, e: 'Akar kembar berarti D = 0. D = k² − 36 = 0, jadi k = 6 atau k = −6.' },
  { id: 'mat1-06', t: 'mat1', lv: 1, src: 'contoh', q: 'Himpunan penyelesaian 2x² − 8 = 0 adalah …', o: ['x = 2 atau x = −2', 'x = 4 atau x = −4', 'x = 2 saja', 'x = √2 atau x = −√2'], a: 0, e: '2x² = 8, maka x² = 4, jadi x = 2 atau x = −2.' },
  { id: 'mat1-07', t: 'mat1', lv: 2, src: 'contoh', q: 'Nilai maksimum dari y = −2x² + 4x + 1 adalah …', o: ['3', '1', '5', '−1'], a: 0, e: 'Puncak di x = −4/(2·(−2)) = 1. Maka y = −2 + 4 + 1 = 3. Karena a < 0, nilai itu maksimum.' },

  /* kim5 */
  { id: 'kim5-01', t: 'kim5', lv: 1, src: 'contoh', q: 'Larutan HCl 0,001 M memiliki pH …', o: ['3', '1', '11', '0,001'], a: 0, e: 'HCl asam kuat valensi 1, [H⁺] = 10⁻³, pH = 3.' },
  { id: 'kim5-02', t: 'kim5', lv: 2, src: 'contoh', q: 'Larutan Ba(OH)₂ 0,005 M memiliki pH …', o: ['12', '11', '2', '13'], a: 0, e: 'Valensi basa 2, [OH⁻] = 2 × 0,005 = 10⁻² M. pOH = 2, jadi pH = 12.' },
  { id: 'kim5-03', t: 'kim5', lv: 1, src: 'contoh', q: 'Larutan dengan pH = 4 memiliki [H⁺] sebesar …', o: ['10⁻⁴ M', '10⁻¹⁰ M', '4 M', '10⁻⁷ M'], a: 0, e: 'pH = −log [H⁺], jadi [H⁺] = 10⁻pH = 10⁻⁴ M.' },
  { id: 'kim5-04', t: 'kim5', lv: 2, src: 'contoh', q: 'CH₃COOH 0,1 M dengan Ka = 10⁻⁵ memiliki pH …', o: ['3', '5', '1', '6'], a: 0, e: '[H⁺] = √(Ka × Ma) = √(10⁻⁵ × 10⁻¹) = 10⁻³. Maka pH = 3.' },
  { id: 'kim5-05', t: 'kim5', lv: 1, src: 'contoh', q: 'Larutan dengan pH 9 pada 25°C bersifat …', o: ['basa', 'asam', 'netral', 'tidak bisa ditentukan'], a: 0, e: 'pH di atas 7 berarti basa pada 25°C.' },
  { id: 'kim5-06', t: 'kim5', lv: 2, src: 'contoh', q: 'H₂SO₄ 0,005 M (anggap terionisasi sempurna) memiliki pH …', o: ['2', '3', '2,3', '1'], a: 0, e: 'Valensi asam 2, [H⁺] = 0,01 = 10⁻². Maka pH = 2.' },

  /* ing2 */
  { id: 'ing2-01', t: 'ing2', lv: 1, src: 'contoh', q: 'If she ___ harder, she would pass the exam.', o: ['studied', 'studies', 'will study', 'had studied'], a: 0, e: 'Klausa utama memakai would + verb (type 2), jadi klausa if memakai simple past: studied.' },
  { id: 'ing2-02', t: 'ing2', lv: 2, src: 'contoh', q: 'If I had known about the test, I ___ earlier.', o: ['would have started', 'would start', 'will start', 'had started'], a: 0, e: 'Klausa if memakai past perfect (type 3), jadi klausa utama memakai would have + past participle.' },
  { id: 'ing2-03', t: 'ing2', lv: 1, src: 'contoh', q: 'If water reaches 100°C, it ___.', o: ['boils', 'will boil', 'would boil', 'boiled'], a: 0, e: 'Fakta umum (type 0): simple present di kedua klausa.' },
  { id: 'ing2-04', t: 'ing2', lv: 1, src: 'contoh', q: 'If I ___ you, I would apologize.', o: ['were', 'am', 'was being', 'had been'], a: 0, e: 'Type 2 formal memakai "were" untuk semua subjek.' },
  { id: 'ing2-05', t: 'ing2', lv: 2, src: 'contoh', q: 'Which sentence is correct?', o: ['If it will rain, we cancel the picnic.', 'If it rains, we will cancel the picnic.', 'If it rained, we will cancel the picnic.', 'If it would rain, we cancel the picnic.'], a: 1, e: 'Type 1: If + simple present, will + verb. Klausa if tidak memakai will atau would.' },
  { id: 'ing2-06', t: 'ing2', lv: 2, src: 'contoh', q: 'I wish I ___ the answer yesterday.', o: ['had known', 'knew', 'know', 'would know'], a: 0, e: 'Wish tentang masa lalu memakai past perfect: had known.' }
  ,
  /* kim12 */
  { id: 'kim12-01', t: 'kim12', lv: 1, src: 'pola', q: 'Jumlah proton, neutron, dan elektron pada ion ³⁵₁₇Cl⁻ berturut-turut adalah …', o: ['17, 18, 18', '17, 18, 17', '18, 17, 18', '17, 17, 18'], a: 0, e: 'Proton = Z = 17. Neutron = 35 − 17 = 18. Anion menerima 1 elektron, jadi elektron = 17 + 1 = 18.' },
  { id: 'kim12-02', t: 'kim12', lv: 1, src: 'pola', q: 'Pasangan atom berikut yang merupakan isoton adalah …', o: ['³¹₁₅P dan ³²₁₆S', '¹⁴₇N dan ¹⁴₆C', '³⁵₁₇Cl dan ³⁷₁₇Cl', '²⁰₁₀Ne dan ²³₁₁Na'], a: 0, e: 'Neutron P = 31 − 15 = 16 dan S = 32 − 16 = 16, jadi isoton. N dan C isobar (A sama). Cl dan Cl isotop (Z sama).' },
  { id: 'kim12-03', t: 'kim12', lv: 2, src: 'pola', q: 'Kelemahan model atom Rutherford adalah …', o: ['Elektron yang mengelilingi inti seharusnya kehilangan energi dan jatuh ke inti, padahal atom stabil', 'Tidak menyebutkan adanya inti atom', 'Menganggap atom sebagai bola pejal tanpa partikel penyusun', 'Menyatakan elektron berada pada lintasan dengan energi tertentu'], a: 0, e: 'Rutherford mengusulkan inti dengan elektron mengelilinginya, tetapi tidak menjelaskan mengapa elektron tidak jatuh ke inti. Pilihan lain adalah ciri model lain (Dalton dan Bohr).' },
  { id: 'kim12-04', t: 'kim12', lv: 2, src: 'pola', q: 'Konfigurasi elektron ion Fe³⁺ (Z = 26) adalah …', o: ['[Ar] 3d⁵', '[Ar] 3d³ 4s²', '[Ar] 3d⁶ 4s²', '[Ar] 3d⁴ 4s¹'], a: 0, e: 'Fe: [Ar] 3d⁶ 4s². Kation melepas elektron kulit terluar dulu: 2 elektron dari 4s, lalu 1 dari 3d. Hasilnya [Ar] 3d⁵.' },
  { id: 'kim12-05', t: 'kim12', lv: 2, src: 'pola', q: 'Keempat bilangan kuantum (n, l, m, s) elektron terakhir atom Al (Z = 13) adalah …', o: ['3, 1, −1, +½', '3, 0, 0, −½', '3, 1, +1, −½', '2, 1, −1, +½'], a: 0, e: 'Al: 1s² 2s² 2p⁶ 3s² 3p¹. Elektron terakhir di 3p: n = 3, l = 1. Elektron pertama di orbital p paling kiri: m = −1, s = +½.' },
  { id: 'kim12-06', t: 'kim12', lv: 2, src: 'pola', q: 'Elektron terakhir suatu unsur memiliki n = 4, l = 0, m = 0, s = −½. Unsur tersebut adalah …', o: ['Ca (Z = 20)', 'K (Z = 19)', 'Sc (Z = 21)', 'Zn (Z = 30)'], a: 0, e: 'n = 4 dan l = 0 berarti 4s. s = −½ berarti elektron kedua, jadi 4s². Konfigurasi berakhir di [Ar] 4s², yaitu Ca. Sc dan Zn berakhir di 3d.' },
  { id: 'kim12-07', t: 'kim12', lv: 2, src: 'pola', q: 'Set bilangan kuantum yang TIDAK mungkin adalah …', o: ['n = 2, l = 2, m = 0', 'n = 3, l = 2, m = −2', 'n = 2, l = 1, m = +1', 'n = 4, l = 3, m = 0'], a: 0, e: 'Nilai l hanya dari 0 sampai n − 1. Untuk n = 2, l maksimum 1, jadi l = 2 tidak mungkin.' },
  { id: 'kim12-08', t: 'kim12', lv: 2, src: 'pola', q: 'Konfigurasi elektron atom Cr (Z = 24) yang paling stabil adalah …', o: ['[Ar] 3d⁵ 4s¹', '[Ar] 3d⁴ 4s²', '[Ar] 3d⁶', '[Ar] 4s² 4p⁴'], a: 0, e: 'Subkulit d setengah penuh (d⁵) lebih stabil, jadi satu elektron 4s berpindah ke 3d.' },
  { id: 'kim12-09', t: 'kim12', lv: 2, src: 'pola', q: 'Ion X²⁺ mempunyai 18 elektron dan 20 neutron. Nomor massa atom X adalah …', o: ['40', '38', '42', '20'], a: 0, e: 'Atom netral X punya 18 + 2 = 20 elektron, jadi Z = 20. Nomor massa A = 20 + 20 = 40.' },
  { id: 'kim12-10', t: 'kim12', lv: 2, src: 'pola', q: 'Jumlah elektron tidak berpasangan pada atom N (Z = 7) adalah …', o: ['3', '1', '2', '5'], a: 0, e: 'N: 1s² 2s² 2p³. Menurut aturan Hund, tiga elektron 2p menempati tiga orbital sendiri-sendiri, jadi 3 elektron tidak berpasangan.' },
  { id: 'kim12-11', t: 'kim12', lv: 2, src: 'pola', q: 'Konfigurasi elektron berikut yang menunjukkan atom Mg (12 elektron) dalam keadaan tereksitasi adalah …', o: ['1s² 2s² 2p⁶ 3s¹ 3p¹', '1s² 2s² 2p⁶ 3s²', '1s² 2s² 2p⁶ 3s¹', '1s² 2s² 2p⁵ 3s²'], a: 0, e: 'Tereksitasi berarti satu elektron naik ke orbital lebih tinggi (3s ke 3p) padahal 3s belum penuh. Pilihan 3s² adalah keadaan dasar. Dua pilihan lain bukan atom dengan 12 elektron.' },

  /* kim14 */
  { id: 'kim14-01', t: 'kim14', lv: 1, src: 'pola', q: 'Unsur dengan konfigurasi elektron kulit 2 8 18 7 terletak pada …', o: ['golongan VIIA, periode 4', 'golongan VIIA, periode 7', 'golongan VA, periode 4', 'golongan VIIB, periode 4'], a: 0, e: 'Ada 4 kulit, jadi periode 4. Elektron terluar 7, jadi golongan VIIA (halogen).' },
  { id: 'kim14-02', t: 'kim14', lv: 2, src: 'pola', q: 'Unsur Z memiliki konfigurasi [Ar] 3d⁵ 4s². Letak unsur Z dalam sistem periodik adalah …', o: ['golongan VIIB, periode 4', 'golongan VIIA, periode 4', 'golongan VB, periode 4', 'golongan VIIB, periode 3'], a: 0, e: 'Kulit terbesar 4, jadi periode 4. Elektron d + s = 5 + 2 = 7, jadi golongan VIIB.' },
  { id: 'kim14-03', t: 'kim14', lv: 2, src: 'pola', q: 'Ion M²⁺ mempunyai konfigurasi elektron [Ar] 3d¹⁰. Unsur M terletak pada …', o: ['golongan IIB, periode 4', 'golongan IIA, periode 4', 'golongan VIIIB, periode 4', 'golongan IIB, periode 3'], a: 0, e: 'M punya 2 elektron lebih banyak: [Ar] 3d¹⁰ 4s². Periode 4, elektron d + s = 12, jadi golongan IIB.' },
  { id: 'kim14-04', t: 'kim14', lv: 1, src: 'pola', q: 'Urutan jari-jari atom dari terbesar ke terkecil untuk Na, Mg, Al, Cl adalah …', o: ['Na > Mg > Al > Cl', 'Cl > Al > Mg > Na', 'Mg > Na > Cl > Al', 'Na > Al > Mg > Cl'], a: 0, e: 'Satu periode, makin ke kanan muatan inti makin besar sehingga jari-jari mengecil.' },
  { id: 'kim14-05', t: 'kim14', lv: 2, src: 'pola', q: 'Pernyataan yang tepat tentang tren unsur-unsur periode 3 dari Na ke Cl adalah …', o: ['Sifat logam berkurang dan sifat asam oksidanya bertambah', 'Jari-jari atom bertambah dan keelektronegatifan bertambah', 'Energi ionisasi berkurang dan sifat oksidator berkurang', 'Sifat basa bertambah dan keelektronegatifan bertambah'], a: 0, e: 'Ke kanan: jari-jari mengecil, EI, EN, dan oksidator naik, sifat logam dan basa turun, sifat asam naik.' },
  { id: 'kim14-06', t: 'kim14', lv: 3, src: 'pola', q: 'Urutan jari-jari dari terbesar ke terkecil untuk O²⁻, F⁻, Na⁺, Mg²⁺ adalah …', o: ['O²⁻ > F⁻ > Na⁺ > Mg²⁺', 'Mg²⁺ > Na⁺ > F⁻ > O²⁻', 'Na⁺ > Mg²⁺ > O²⁻ > F⁻', 'F⁻ > O²⁻ > Mg²⁺ > Na⁺'], a: 0, e: 'Semua punya 10 elektron (isoelektron). Makin banyak proton, tarikan ke inti makin kuat dan jari-jari makin kecil: O (8 proton) paling sedikit sehingga jari-jarinya terbesar, Mg (12 proton) paling kecil.' },
  { id: 'kim14-07', t: 'kim14', lv: 3, src: 'pola', q: 'Energi ionisasi pertama Mg lebih besar daripada Al. Alasan yang tepat adalah …', o: ['Elektron 3p Al lebih mudah dilepas daripada elektron 3s² Mg yang subkulitnya penuh', 'Jari-jari Mg lebih besar daripada Al', 'Muatan inti Al lebih kecil daripada Mg', 'Al lebih elektronegatif daripada Mg'], a: 0, e: 'Mg melepas elektron dari 3s yang penuh dan stabil, sedangkan Al melepas elektron 3p yang berenergi sedikit lebih tinggi. Itu anomali tren energi ionisasi.' },
  { id: 'kim14-08', t: 'kim14', lv: 2, src: 'pola', q: 'Bilangan oksidasi tertinggi dan terendah unsur golongan VIA berturut-turut adalah …', o: ['+6 dan −2', '+6 dan −6', '+2 dan −6', '+4 dan −4'], a: 0, e: 'Tertinggi = nomor golongan = +6. Terendah = nomor golongan − 8 = −2 (misalnya S dalam H₂S).' },
  { id: 'kim14-09', t: 'kim14', lv: 2, src: 'pola', q: 'Dari F₂ ke I₂ dalam golongan halogen …', o: ['kekuatan oksidator melemah dan titik didih naik', 'kekuatan oksidator menguat dan titik didih naik', 'kekuatan oksidator melemah dan titik didih turun', 'kekuatan oksidator menguat dan titik didih turun'], a: 0, e: 'Ke bawah, keelektronegatifan turun sehingga oksidator melemah. Mr bertambah sehingga gaya London makin kuat dan titik didih naik.' },
  { id: 'kim14-10', t: 'kim14', lv: 1, src: 'pola', q: 'Unsur P berkonfigurasi [Ne] 3s². Unsur yang sifat kimianya paling mirip dengan P berkonfigurasi …', o: ['[Ar] 4s²', '[Ne] 3s² 3p¹', '[Ar] 4s¹', '[He] 2s² 2p⁶'], a: 0, e: 'Sifat mirip jika elektron valensi sama dan golongannya sama. 3s² dan 4s² sama-sama golongan IIA.' },

  /* kim15 */
  { id: 'kim15-01', t: 'kim15', lv: 1, src: 'pola', q: 'Unsur X (Z = 12) berikatan dengan unsur Y (Z = 17). Rumus dan jenis ikatannya adalah …', o: ['XY₂, ion', 'X₂Y, ion', 'XY₂, kovalen', 'XY, kovalen'], a: 0, e: 'X (2 8 2) melepas 2 elektron menjadi X²⁺. Y (2 8 7) menerima 1 elektron menjadi Y⁻. Logam + nonlogam: ikatan ion, rumus XY₂.' },
  { id: 'kim15-02', t: 'kim15', lv: 2, src: 'pola', q: 'Unsur P (Z = 15) berikatan dengan Cl (Z = 17) membentuk PCl₃. Pernyataan yang tepat adalah …', o: ['Ikatan kovalen dan atom P memiliki 1 pasangan elektron bebas', 'Ikatan ion karena beda keelektronegatifan besar', 'Ikatan kovalen dan atom P tidak memiliki pasangan elektron bebas', 'Semua ikatan P–Cl adalah kovalen koordinasi'], a: 0, e: 'P punya 5 elektron valensi, 3 dipakai berikatan, 2 tersisa sebagai 1 pasangan bebas. Keduanya nonlogam, jadi kovalen.' },
  { id: 'kim15-03', t: 'kim15', lv: 1, src: 'pola', q: 'Zat Q memiliki titik leleh tinggi, padatannya tidak menghantar listrik, tetapi lelehan dan larutannya menghantar listrik. Zat Q adalah senyawa …', o: ['ion', 'kovalen polar', 'kovalen nonpolar', 'logam'], a: 0, e: 'Itu ciri senyawa ion: ion terkunci di padatan, bebas bergerak saat meleleh atau larut.' },
  { id: 'kim15-04', t: 'kim15', lv: 2, src: 'pola', q: 'Spesi berikut yang mengandung ikatan kovalen koordinasi adalah …', o: ['NH₄⁺', 'CH₄', 'CO₂', 'H₂O'], a: 0, e: 'NH₄⁺ terbentuk saat NH₃ memberikan pasangan bebasnya ke H⁺. Pasangan elektron berasal dari satu atom saja (N).' },
  { id: 'kim15-05', t: 'kim15', lv: 2, src: 'pola', q: 'Titik didih HF (±20 °C) jauh lebih tinggi daripada HCl (±−85 °C) padahal Mr HF lebih kecil. Penyebabnya adalah …', o: ['adanya ikatan hidrogen antarmolekul HF', 'ikatan kovalen HF lebih kuat daripada HCl', 'gaya London HF lebih kuat karena Mr lebih besar', 'HF merupakan senyawa ion'], a: 0, e: 'H yang terikat pada F membentuk ikatan hidrogen antarmolekul, yang jauh lebih kuat daripada dipol–dipol HCl.' },
  { id: 'kim15-06', t: 'kim15', lv: 2, src: 'pola', q: 'Titik didih gas mulia naik dari He ke Xe. Hal ini terjadi karena …', o: ['gaya London makin kuat seiring bertambahnya massa dan jumlah elektron', 'terbentuk ikatan hidrogen antaratom', 'ikatan ionnya makin kuat', 'molekulnya bersifat polar'], a: 0, e: 'Gas mulia monoatomik dan nonpolar. Satu-satunya gaya antaratom adalah gaya London, yang makin kuat jika elektron makin banyak.' },
  { id: 'kim15-07', t: 'kim15', lv: 2, src: 'pola', q: 'Bentuk molekul H₂O dan BeCl₂ berturut-turut adalah …', o: ['bentuk V dan linear', 'linear dan bentuk V', 'trigonal piramida dan linear', 'bentuk V dan segitiga datar'], a: 0, e: 'H₂O: 2 ikatan + 2 pasangan bebas (AX₂E₂), bentuk V. BeCl₂: 2 ikatan tanpa pasangan bebas (AX₂), linear.' },
  { id: 'kim15-08', t: 'kim15', lv: 3, src: 'pola', q: 'Bentuk molekul IF₅ dan hibridisasi atom pusatnya berturut-turut adalah …', o: ['piramida segiempat, sp³d²', 'trigonal bipiramida, sp³d', 'oktahedral, sp³d²', 'bentuk T, sp³d'], a: 0, e: 'I punya 7 elektron valensi, 5 dipakai ikatan, 1 pasangan bebas. Domain = 6 (AX₅E): piramida segiempat, hibridisasi sp³d².' },
  { id: 'kim15-09', t: 'kim15', lv: 2, src: 'pola', q: 'Molekul berikut yang nonpolar walaupun memiliki ikatan polar adalah …', o: ['CO₂', 'NH₃', 'H₂O', 'HCl'], a: 0, e: 'CO₂ linear dan simetris, sehingga dipol kedua ikatan C=O saling meniadakan. Tiga molekul lain tidak simetris atau diatomik beda unsur.' },
  { id: 'kim15-10', t: 'kim15', lv: 2, src: 'pola', q: 'Hibridisasi atom pusat pada CH₄ dan BF₃ berturut-turut adalah …', o: ['sp³ dan sp²', 'sp² dan sp³', 'sp³ dan sp', 'sp dan sp²'], a: 0, e: 'CH₄ punya 4 domain (sp³, tetrahedral). BF₃ punya 3 domain (sp², segitiga datar).' },
  { id: 'kim15-11', t: 'kim15', lv: 2, src: 'pola', q: 'Molekul berikut yang atom pusatnya tidak memenuhi aturan oktet (elektron kurang dari 8) adalah …', o: ['BF₃', 'CF₄', 'NH₃', 'H₂O'], a: 0, e: 'B punya 3 elektron valensi dan membentuk 3 ikatan, sehingga hanya 6 elektron di sekitar B. Atom pusat lain mencapai 8.' },

  /* kim16 */
  { id: 'kim16-01', t: 'kim16', lv: 1, src: 'pola', q: 'Nama senyawa Fe₂O₃ adalah …', o: ['besi(III) oksida', 'besi(II) oksida', 'difero trioksida', 'besi oksida(III)'], a: 0, e: 'Dua Fe bermuatan total +6 mengimbangi tiga O²⁻ (−6), jadi Fe³⁺. Namanya besi(III) oksida.' },
  { id: 'kim16-02', t: 'kim16', lv: 2, src: 'pola', q: 'Nama senyawa N₂O₅ adalah …', o: ['dinitrogen pentaoksida', 'nitrogen pentaoksida', 'dinitrogen oksida', 'nitrogen(II) oksida'], a: 0, e: 'Dua atom N diberi awalan di-, lima atom O diberi awalan penta-. Mono hanya dihilangkan untuk unsur pertama yang jumlahnya satu.' },
  { id: 'kim16-03', t: 'kim16', lv: 1, src: 'pola', q: 'Reaksi Al + O₂ → Al₂O₃ setara dengan koefisien Al, O₂, Al₂O₃ berturut-turut …', o: ['4, 3, 2', '2, 3, 1', '2, 1, 1', '3, 2, 1'], a: 0, e: 'Kanan punya 4 Al dan 6 O jika koefisien Al₂O₃ = 2. Maka Al = 4 dan O₂ = 3.' },
  { id: 'kim16-04', t: 'kim16', lv: 2, src: 'pola', q: 'Pada reaksi C₃H₈ + O₂ → CO₂ + H₂O, koefisien O₂ setelah disetarakan adalah …', o: ['5', '3', '4', '10'], a: 0, e: 'C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. O di kanan: 3·2 + 4 = 10, jadi O₂ = 5.' },
  { id: 'kim16-05', t: 'kim16', lv: 1, src: 'pola', q: 'Rumus empiris dari C₄H₈O₂ adalah …', o: ['C₂H₄O', 'CH₂O', 'C₄H₈O₂', 'C₂H₂O'], a: 0, e: 'Bagi semua indeks dengan 2, perbandingan paling sederhananya C : H : O = 2 : 4 : 1.' },
  { id: 'kim16-06', t: 'kim16', lv: 2, src: 'pola', q: 'Perbandingan massa Mg : O dalam MgO adalah 3 : 2. Jika 6 g Mg direaksikan dengan 6 g O₂, massa MgO yang terbentuk adalah …', o: ['10 g', '12 g', '9 g', '6 g'], a: 0, e: '6 g Mg butuh 4 g O. O bersisa 2 g. MgO = 6 + 4 = 10 g (Proust dan Lavoisier).' },
  { id: 'kim16-07', t: 'kim16', lv: 2, src: 'pola', q: 'Senyawa I mengandung 28 g N dan 16 g O. Senyawa II mengandung 14 g N dan 16 g O. Untuk massa N yang sama, perbandingan massa O di senyawa I : II adalah …', o: ['1 : 2', '1 : 1', '2 : 3', '1 : 4'], a: 0, e: 'Samakan N: senyawa II menjadi 28 g N dan 32 g O. Perbandingan O = 16 : 32 = 1 : 2. Itu hukum Dalton (perbandingan berganda).' },
  { id: 'kim16-08', t: 'kim16', lv: 1, src: 'pola', q: 'Pada P dan T yang sama, 6 L gas H₂ bereaksi sempurna dengan O₂ menurut 2H₂ + O₂ → 2H₂O (uap). Volume uap air yang terbentuk adalah …', o: ['6 L', '3 L', '12 L', '4 L'], a: 0, e: 'Perbandingan volume sama dengan koefisien. H₂ : H₂O = 2 : 2, jadi 6 L H₂ menghasilkan 6 L uap air.' },
  { id: 'kim16-09', t: 'kim16', lv: 1, src: 'pola', q: 'Percobaan membuat CaCO₃ dari larutan Na₂CO₃ dan CaCl₂ di wadah tertutup menunjukkan massa sebelum dan sesudah reaksi sama. Hukum yang sesuai adalah …', o: ['Hukum Kekekalan Massa', 'Hukum Perbandingan Tetap', 'Hukum Perbandingan Berganda', 'Hukum Perbandingan Volume'], a: 0, e: 'Massa total tidak berubah sebelum dan sesudah reaksi: hukum Lavoisier.' },
  { id: 'kim16-10', t: 'kim16', lv: 2, src: 'pola', q: 'Rumus kimia aluminium sulfat adalah …', o: ['Al₂(SO₄)₃', 'Al₃(SO₄)₂', 'AlSO₄', 'Al(SO₄)₃'], a: 0, e: 'Al³⁺ dan SO₄²⁻. Silang muatan: Al₂(SO₄)₃. Tanda kurung dipakai karena ion poliatomik lebih dari satu.' },

  /* kim1 */
  { id: 'kim1-01', t: 'kim1', lv: 1, src: 'pola', q: 'Jumlah mol 11 g CO₂ (Ar C = 12, O = 16) adalah …', o: ['0,25 mol', '0,5 mol', '2,5 mol', '4 mol'], a: 0, e: 'Mr CO₂ = 44. Mol = 11 / 44 = 0,25.' },
  { id: 'kim1-02', t: 'kim1', lv: 1, src: 'pola', q: 'Jumlah molekul dalam 0,2 mol H₂O (L = 6,02 × 10²³) adalah …', o: ['1,204 × 10²³', '3,01 × 10²³', '1,204 × 10²⁴', '6,02 × 10²²'], a: 0, e: 'Partikel = mol × L = 0,2 × 6,02 × 10²³ = 1,204 × 10²³.' },
  { id: 'kim1-03', t: 'kim1', lv: 1, src: 'pola', q: 'Sebanyak 4 g NaOH (Mr = 40) dilarutkan hingga volume 500 mL. Molaritas larutan adalah …', o: ['0,2 M', '0,1 M', '0,5 M', '2 M'], a: 0, e: 'Mol = 4 / 40 = 0,1. Volume 0,5 L. M = 0,1 / 0,5 = 0,2 M.' },
  { id: 'kim1-04', t: 'kim1', lv: 1, src: 'pola', q: 'Sebanyak 50 mL larutan HCl 2 M diencerkan hingga volume 200 mL. Molaritas setelah pengenceran adalah …', o: ['0,5 M', '0,25 M', '1 M', '4 M'], a: 0, e: 'M₁V₁ = M₂V₂ → 2 × 50 = M₂ × 200, jadi M₂ = 0,5 M.' },
  { id: 'kim1-05', t: 'kim1', lv: 2, src: 'pola', q: 'Reaksi N₂ + 3H₂ → 2NH₃. Jika 2 mol N₂ dicampur 3 mol H₂, pereaksi pembatas dan sisa pereaksi adalah …', o: ['H₂ pembatas; sisa 1 mol N₂', 'N₂ pembatas; sisa 1 mol H₂', 'H₂ pembatas; sisa 2 mol N₂', 'tidak ada sisa'], a: 0, e: 'N₂: 2/1 = 2. H₂: 3/3 = 1. H₂ habis lebih dulu. N₂ yang bereaksi 1 mol, sisa 1 mol.' },
  { id: 'kim1-06', t: 'kim1', lv: 2, src: 'pola', q: 'Sebanyak 5,4 g Al (Ar = 27) direaksikan dengan HCl berlebih: 2Al + 6HCl → 2AlCl₃ + 3H₂. Volume H₂ pada STP adalah …', o: ['6,72 L', '4,48 L', '2,24 L', '13,44 L'], a: 0, e: 'Mol Al = 5,4 / 27 = 0,2. Mol H₂ = 3/2 × 0,2 = 0,3. Volume = 0,3 × 22,4 = 6,72 L.' },
  { id: 'kim1-07', t: 'kim1', lv: 2, src: 'pola', q: 'Senyawa mengandung 40% C, 6,7% H, dan 53,3% O dengan Mr = 60. Rumus molekulnya adalah … (Ar C = 12, H = 1, O = 16)', o: ['C₂H₄O₂', 'CH₂O', 'C₃H₆O₃', 'C₄H₈O₄'], a: 0, e: 'Mol C : H : O = 3,33 : 6,7 : 3,33 = 1 : 2 : 1, RE = CH₂O (Mr 30). n = 60/30 = 2, jadi C₂H₄O₂.' },
  { id: 'kim1-08', t: 'kim1', lv: 3, src: 'pola', q: 'Sebanyak 2,5 g garam hidrat CuSO₄·xH₂O dipanaskan hingga tersisa 1,6 g CuSO₄ anhidrat (Mr CuSO₄ = 160, H₂O = 18). Nilai x adalah …', o: ['5', '4', '7', '10'], a: 0, e: 'Air yang hilang = 0,9 g = 0,05 mol. CuSO₄ = 1,6 / 160 = 0,01 mol. x = 0,05 / 0,01 = 5.' },
  { id: 'kim1-09', t: 'kim1', lv: 2, src: 'pola', q: 'Massa Fe dalam 40 g Fe₂O₃ (Ar Fe = 56, O = 16) adalah …', o: ['28 g', '14 g', '56 g', '20 g'], a: 0, e: 'Mr Fe₂O₃ = 160. Kadar Fe = 112/160 = 70%. Massa Fe = 70% × 40 = 28 g.' },
  { id: 'kim1-10', t: 'kim1', lv: 2, src: 'pola', q: 'Pada P dan T yang sama, 2 L gas N₂ mengandung 4 × 10²² molekul. Jumlah molekul dalam 5 L gas O₂ pada kondisi sama adalah …', o: ['1 × 10²³', '2 × 10²²', '8 × 10²²', '4 × 10²³'], a: 0, e: 'Hipotesis Avogadro: jumlah molekul sebanding dengan volume. (5/2) × 4 × 10²² = 1 × 10²³.' }
  ,
  /* kim2 */
  { id: 'kim2-01', t: 'kim2', lv: 1, src: 'pola', q: 'Suatu reaksi memiliki ΔH = −120 kJ. Pernyataan yang tepat adalah …', o: ['Reaksi melepas kalor dan suhu lingkungan naik', 'Reaksi menyerap kalor dan suhu lingkungan turun', 'Entalpi produk lebih besar daripada reaktan', 'Reaksi tidak melibatkan perpindahan kalor'], a: 0, e: 'ΔH negatif berarti eksoterm: kalor berpindah dari sistem ke lingkungan sehingga suhu lingkungan naik. Entalpi produk lebih rendah.' },
  { id: 'kim2-02', t: 'kim2', lv: 1, src: 'pola', q: 'Persamaan yang menyatakan entalpi pembentukan standar CO₂ adalah …', o: ['C(s) + O₂(g) → CO₂(g)', 'CO(g) + ½O₂(g) → CO₂(g)', '2C(s) + 2O₂(g) → 2CO₂(g)', 'C(g) + O₂(g) → CO₂(g)'], a: 0, e: 'Pembentukan: 1 mol senyawa dari unsur-unsurnya dalam bentuk paling stabil, yaitu C padat dan O₂ gas.' },
  { id: 'kim2-03', t: 'kim2', lv: 1, src: 'pola', q: 'Diketahui 2H₂(g) + O₂(g) → 2H₂O(l) ΔH = −572 kJ. ΔH untuk H₂O(l) → H₂(g) + ½O₂(g) adalah …', o: ['+286 kJ', '−286 kJ', '+572 kJ', '−572 kJ'], a: 0, e: 'Bagi 2 (untuk 1 mol H₂O): −286 kJ. Dibalik: tanda berubah jadi +286 kJ.' },
  { id: 'kim2-04', t: 'kim2', lv: 2, src: 'pola', q: 'Sebanyak 50 mL HCl 1 M dicampur 50 mL NaOH 1 M. Suhu naik 6,5 °C (massa jenis 1 g/mL, c = 4,2 J/g °C). ΔH penetralan per mol air adalah …', o: ['−54,6 kJ/mol', '+54,6 kJ/mol', '−5,46 kJ/mol', '−109,2 kJ/mol'], a: 0, e: 'q = 100 × 4,2 × 6,5 = 2.730 J. Mol air = 0,05. ΔH = −2.730 / 0,05 = −54.600 J/mol. Suhu naik berarti eksoterm (negatif).' },
  { id: 'kim2-05', t: 'kim2', lv: 2, src: 'pola', q: 'Diketahui C + O₂ → CO₂ ΔH = −394 kJ dan CO + ½O₂ → CO₂ ΔH = −283 kJ. ΔH untuk C + ½O₂ → CO adalah …', o: ['−111 kJ', '+111 kJ', '−677 kJ', '+677 kJ'], a: 0, e: 'Reaksi pertama tetap, reaksi kedua dibalik (+283). Jumlah: −394 + 283 = −111 kJ.' },
  { id: 'kim2-06', t: 'kim2', lv: 2, src: 'pola', q: 'ΔHf CH₄ = −75, CO₂ = −394, H₂O(l) = −286 kJ/mol. ΔH reaksi CH₄ + 2O₂ → CO₂ + 2H₂O adalah …', o: ['−891 kJ', '−605 kJ', '+891 kJ', '−1.041 kJ'], a: 0, e: 'ΔH = [−394 + 2(−286)] − [−75 + 0] = −966 + 75 = −891 kJ.' },
  { id: 'kim2-07', t: 'kim2', lv: 2, src: 'pola', q: 'Energi ikatan H–H = 436, Cl–Cl = 243, H–Cl = 432 kJ/mol. ΔH untuk H₂ + Cl₂ → 2HCl adalah …', o: ['−185 kJ', '+185 kJ', '−864 kJ', '+679 kJ'], a: 0, e: 'Putus: 436 + 243 = 679. Bentuk: 2 × 432 = 864. ΔH = 679 − 864 = −185 kJ.' },
  { id: 'kim2-08', t: 'kim2', lv: 2, src: 'pola', q: 'Entalpi pembakaran oktana (Mm = 114 g/mol) adalah −5.460 kJ/mol. Kalor yang dilepas pada pembakaran sempurna 11,4 g oktana adalah …', o: ['546 kJ', '5.460 kJ', '54,6 kJ', '620 kJ'], a: 0, e: 'Mol = 11,4 / 114 = 0,1. Kalor = 0,1 × 5.460 = 546 kJ.' },
  { id: 'kim2-09', t: 'kim2', lv: 2, src: 'pola', q: 'Kompres dingin instan terasa dingin saat amonium nitrat dilarutkan dalam air. Pernyataan yang tepat adalah …', o: ['Pelarutan bersifat endoterm, kalor berpindah dari lingkungan ke sistem, ΔH positif', 'Pelarutan bersifat eksoterm, ΔH negatif', 'Entalpi produk lebih rendah daripada reaktan', 'Tidak ada perpindahan kalor'], a: 0, e: 'Terasa dingin berarti sistem menyerap kalor dari lingkungan (tangan): endoterm, ΔH positif.' },
  { id: 'kim2-10', t: 'kim2', lv: 3, src: 'pola', q: 'Diketahui S + O₂ → SO₂ ΔH = −297 kJ dan 2SO₂ + O₂ → 2SO₃ ΔH = −198 kJ. ΔH untuk 2S + 3O₂ → 2SO₃ adalah …', o: ['−792 kJ', '−495 kJ', '−396 kJ', '−594 kJ'], a: 0, e: 'Reaksi pertama dikali 2: ΔH = −594. Tambahkan reaksi kedua (−198). Total = −792 kJ.' },
  { id: 'kim2-11', t: 'kim2', lv: 3, src: 'pola', q: 'Energi ikatan (kJ/mol): C=C 614, C–C 348, C–H 413, H–H 436. ΔH untuk C₂H₄ + H₂ → C₂H₆ adalah …', o: ['−124 kJ', '+124 kJ', '−1.174 kJ', '+1.050 kJ'], a: 0, e: 'Putus: C=C + H–H = 614 + 436 = 1.050. Bentuk: C–C + 2 C–H = 348 + 826 = 1.174. ΔH = 1.050 − 1.174 = −124 kJ.' },

  /* kim3 */
  { id: 'kim3-01', t: 'kim3', lv: 1, src: 'pola', q: 'Pada reaksi 2N₂O₅ → 4NO₂ + O₂, laju pembentukan O₂ = 0,01 M/s. Laju pembentukan NO₂ adalah …', o: ['0,04 M/s', '0,01 M/s', '0,02 M/s', '0,005 M/s'], a: 0, e: 'Laju sebanding dengan koefisien. NO₂ : O₂ = 4 : 1, jadi laju NO₂ = 4 × 0,01 = 0,04 M/s.' },
  { id: 'kim3-02', t: 'kim3', lv: 2, src: 'pola', q: 'Data percobaan: (1) [A]=0,1 M, [B]=0,1 M, v=2; (2) [A]=0,2 M, [B]=0,1 M, v=8; (3) [A]=0,1 M, [B]=0,2 M, v=4 (M/s). Persamaan laju reaksinya adalah …', o: ['v = k[A]²[B]', 'v = k[A][B]²', 'v = k[A][B]', 'v = k[A]²[B]²'], a: 0, e: '(1)→(2): [A] ×2, laju ×4, orde A = 2. (1)→(3): [B] ×2, laju ×2, orde B = 1.' },
  { id: 'kim3-03', t: 'kim3', lv: 1, src: 'pola', q: 'Reaksi berorde nol terhadap zat X. Pernyataan yang tepat adalah …', o: ['Laju reaksi tidak dipengaruhi konsentrasi X', 'Laju reaksi berbanding lurus dengan konsentrasi X', 'Laju reaksi berbanding lurus dengan kuadrat konsentrasi X', 'X tidak ikut bereaksi sama sekali'], a: 0, e: 'Orde nol: v = k[X]⁰ = k, jadi laju tidak berubah ketika [X] diubah.' },
  { id: 'kim3-04', t: 'kim3', lv: 1, src: 'pola', q: 'Reaksi berorde 2 terhadap zat A. Jika konsentrasi A dijadikan 3 kali semula, laju reaksi menjadi … kali.', o: ['9', '3', '6', '27'], a: 0, e: 'Laju ∝ [A]², jadi 3² = 9 kali.' },
  { id: 'kim3-05', t: 'kim3', lv: 2, src: 'pola', q: 'Pada 20 °C laju suatu reaksi 4 × 10⁻³ M/s. Laju naik 3 kali tiap kenaikan 10 °C. Laju pada 40 °C adalah …', o: ['3,6 × 10⁻² M/s', '1,2 × 10⁻² M/s', '1,2 × 10⁻¹ M/s', '8 × 10⁻³ M/s'], a: 0, e: 'Naik 20 °C = 2 × 10 °C, jadi laju × 3² = 9. 4 × 10⁻³ × 9 = 3,6 × 10⁻² M/s.' },
  { id: 'kim3-06', t: 'kim3', lv: 2, src: 'pola', q: 'Reaksi selesai dalam 80 detik pada 25 °C. Laju naik 2 kali tiap kenaikan 10 °C. Waktu reaksi pada 55 °C adalah …', o: ['10 detik', '20 detik', '40 detik', '160 detik'], a: 0, e: 'Naik 30 °C berarti laju ×2³ = 8. Waktu berbanding terbalik: 80 / 8 = 10 detik.' },
  { id: 'kim3-07', t: 'kim3', lv: 2, src: 'pola', q: 'Pernyataan yang tepat tentang peran katalis adalah …', o: ['Menurunkan energi aktivasi melalui jalur reaksi lain tanpa mengubah ΔH', 'Menaikkan energi aktivasi agar reaksi lebih terkendali', 'Mengubah ΔH reaksi menjadi lebih negatif', 'Habis terpakai selama reaksi'], a: 0, e: 'Katalis memberi jalur dengan Ea lebih rendah. ΔH tidak berubah, dan katalis kembali utuh di akhir reaksi.' },
  { id: 'kim3-08', t: 'kim3', lv: 1, src: 'pola', q: 'Zn direaksikan dengan HCl pada 25 °C. Percobaan yang berlangsung paling cepat adalah …', o: ['Zn serbuk dengan HCl 2 M', 'Zn keping dengan HCl 1 M', 'Zn serbuk dengan HCl 1 M', 'Zn keping dengan HCl 2 M'], a: 0, e: 'Serbuk memiliki luas permukaan lebih besar, dan konsentrasi 2 M lebih pekat. Keduanya mempercepat tumbukan.' },
  { id: 'kim3-09', t: 'kim3', lv: 3, src: 'pola', q: 'Zat A terurai dengan orde 1 dan waktu paruh 10 menit. Jika [A] mula-mula 0,8 M, konsentrasi A setelah 30 menit adalah …', o: ['0,1 M', '0,2 M', '0,4 M', '0,05 M'], a: 0, e: '30 menit = 3 kali waktu paruh. Sisa = 0,8 × (½)³ = 0,1 M.' },
  { id: 'kim3-10', t: 'kim3', lv: 1, src: 'pola', q: 'Tumbukan antarpartikel menghasilkan reaksi (tumbukan efektif) jika …', o: ['orientasi tepat dan energi minimal sama dengan atau lebih besar dari energi aktivasi', 'jumlah tumbukannya sangat banyak', 'energinya lebih kecil dari energi aktivasi', 'terjadi pada suhu rendah'], a: 0, e: 'Tumbukan efektif butuh dua syarat: orientasi yang tepat dan energi cukup (≥ Ea).' },
  { id: 'kim3-11', t: 'kim3', lv: 2, src: 'pola', q: 'Data: (1) [NO]=0,1, [H₂]=0,1, v=3; (2) [NO]=0,2, [H₂]=0,1, v=12; (3) [NO]=0,2, [H₂]=0,2, v=24 (M/s). Orde total reaksi adalah …', o: ['3', '2', '1', '4'], a: 0, e: '(1)→(2): [NO] ×2, laju ×4, orde NO = 2. (2)→(3): [H₂] ×2, laju ×2, orde H₂ = 1. Total 2 + 1 = 3.' },

  /* kim4 */
  { id: 'kim4-01', t: 'kim4', lv: 1, src: 'pola', q: 'Ungkapan Kc untuk Fe₃O₄(s) + 4CO(g) ⇌ 3Fe(s) + 4CO₂(g) adalah …', o: ['[CO₂]⁴ / [CO]⁴', '[Fe]³[CO₂]⁴ / ([Fe₃O₄][CO]⁴)', '[CO]⁴ / [CO₂]⁴', '[Fe]³ / [Fe₃O₄]'], a: 0, e: 'Padatan (Fe₃O₄ dan Fe) tidak ditulis. Hanya gas yang masuk: produk di atas, reaktan di bawah.' },
  { id: 'kim4-02', t: 'kim4', lv: 1, src: 'pola', q: 'Ungkapan Kc untuk CaCO₃(s) ⇌ CaO(s) + CO₂(g) adalah …', o: ['Kc = [CO₂]', 'Kc = [CaO][CO₂] / [CaCO₃]', 'Kc = [CaCO₃] / [CO₂]', 'Kc = [CaO] / [CaCO₃]'], a: 0, e: 'Hanya CO₂ yang berwujud gas, padatan tidak ditulis.' },
  { id: 'kim4-03', t: 'kim4', lv: 2, src: 'pola', q: 'Sebanyak 2 mol N₂O₄ dalam wadah 2 L terurai menurut N₂O₄ ⇌ 2NO₂ dengan derajat disosiasi 0,5. Nilai Kc adalah …', o: ['2', '1', '0,5', '4'], a: 0, e: 'Terurai 1 mol. Setimbang: N₂O₄ 1 mol (0,5 M) dan NO₂ 2 mol (1 M). Kc = 1² / 0,5 = 2.' },
  { id: 'kim4-04', t: 'kim4', lv: 2, src: 'pola', q: 'Untuk H₂ + I₂ ⇌ 2HI, K = 50 pada suhu tertentu. Nilai K untuk 2HI ⇌ H₂ + I₂ pada suhu sama adalah …', o: ['0,02', '50', '100', '2.500'], a: 0, e: 'Reaksi dibalik, K menjadi 1/K = 1/50 = 0,02.' },
  { id: 'kim4-05', t: 'kim4', lv: 2, src: 'pola', q: 'Untuk H₂ + I₂ ⇌ 2HI, K = 50. Dalam campuran: [H₂] = 0,1 M, [I₂] = 0,1 M, [HI] = 1 M. Pernyataan yang tepat adalah …', o: ['Qc = 100 sehingga reaksi bergeser ke kiri', 'Qc = 100 sehingga reaksi bergeser ke kanan', 'Qc = 50 sehingga sudah setimbang', 'Qc = 10 sehingga reaksi bergeser ke kiri'], a: 0, e: 'Qc = 1² / (0,1 × 0,1) = 100 > K, jadi produk terlalu banyak dan reaksi bergeser ke kiri.' },
  { id: 'kim4-06', t: 'kim4', lv: 2, src: 'pola', q: 'Reaksi kesetimbangan berikut yang hasilnya bertambah jika volume sistem diperkecil adalah …', o: ['N₂(g) + 3H₂(g) ⇌ 2NH₃(g)', 'H₂(g) + I₂(g) ⇌ 2HI(g)', 'N₂O₄(g) ⇌ 2NO₂(g)', 'CaCO₃(s) ⇌ CaO(s) + CO₂(g)'], a: 0, e: 'Volume diperkecil menggeser ke sisi koefisien gas lebih kecil. Hanya reaksi NH₃ yang berubah dari 4 mol gas menjadi 2 mol gas.' },
  { id: 'kim4-07', t: 'kim4', lv: 2, src: 'pola', q: 'Pada N₂(g) + 3H₂(g) ⇌ 2NH₃(g) ΔH = −92 kJ, kenaikan suhu akan …', o: ['menggeser kesetimbangan ke kiri dan menurunkan nilai K', 'menggeser kesetimbangan ke kanan dan menaikkan nilai K', 'menggeser kesetimbangan ke kiri tanpa mengubah K', 'tidak berpengaruh'], a: 0, e: 'Suhu naik menggeser ke arah endoterm (reaksi balik). Karena reaksi maju eksoterm, K mengecil.' },
  { id: 'kim4-08', t: 'kim4', lv: 1, src: 'pola', q: 'Penambahan katalis pada suatu sistem kesetimbangan akan …', o: ['mempercepat tercapainya kesetimbangan tanpa menggeser posisinya', 'menggeser kesetimbangan ke arah produk', 'menaikkan nilai K', 'menurunkan nilai K'], a: 0, e: 'Katalis mempercepat reaksi maju dan balik sama besar, jadi posisi dan nilai K tidak berubah.' },
  { id: 'kim4-09', t: 'kim4', lv: 2, src: 'pola', q: 'Hubungan Kp dan Kc untuk 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) adalah …', o: ['Kp = Kc (RT)⁻¹', 'Kp = Kc (RT)', 'Kp = Kc', 'Kp = Kc (RT)²'], a: 0, e: 'Δn = 2 − (2 + 1) = −1, jadi Kp = Kc (RT)⁻¹.' },
  { id: 'kim4-10', t: 'kim4', lv: 2, src: 'pola', q: 'Pada PCl₅(g) ⇌ PCl₃(g) + Cl₂(g), tekanan parsial setimbang PCl₅ = 2 atm, PCl₃ = 4 atm, dan Cl₂ = 4 atm. Nilai Kp adalah …', o: ['8', '2', '4', '16'], a: 0, e: 'Kp = (4 × 4) / 2 = 8.' },
  { id: 'kim4-11', t: 'kim4', lv: 3, src: 'pola', q: 'Sebanyak 4 mol PCl₅ dimasukkan ke wadah 2 L. Setelah setimbang PCl₅ ⇌ PCl₃ + Cl₂, derajat disosiasinya 0,5. Nilai Kc adalah …', o: ['1', '0,5', '2', '4'], a: 0, e: 'Terurai 2 mol. Setimbang: PCl₅ 2 mol, PCl₃ 2 mol, Cl₂ 2 mol. Konsentrasi masing-masing 1 M, jadi Kc = (1 × 1) / 1 = 1.' },
  { id: 'kim4-12', t: 'kim4', lv: 2, src: 'pola', q: 'Untuk memperbanyak NH₃ pada N₂ + 3H₂ ⇌ 2NH₃ (ΔH negatif), strategi yang tepat adalah …', o: ['menaikkan tekanan dan mengeluarkan NH₃ dari sistem', 'menaikkan suhu sangat tinggi dan menurunkan tekanan', 'menambah katalis lebih banyak saja', 'mengurangi H₂ dan menambah NH₃'], a: 0, e: 'Tekanan tinggi menggeser ke 2 mol gas. Mengeluarkan produk menggeser ke kanan. Suhu terlalu tinggi justru merugikan karena reaksi eksoterm, dan katalis tidak menggeser kesetimbangan.' }
  ,
  /* kim5 tambahan */
  { id: 'kim5-07', t: 'kim5', lv: 1, src: 'pola', q: 'Basa konjugasi dari H₂PO₄⁻ adalah …', o: ['HPO₄²⁻', 'H₃PO₄', 'PO₄³⁻', 'H₃O⁺'], a: 0, e: 'Basa konjugasi diperoleh dengan mengurangi satu H⁺: H₂PO₄⁻ → HPO₄²⁻.' },
  { id: 'kim5-08', t: 'kim5', lv: 2, src: 'pola', q: 'Pada reaksi NH₃ + H₂O ⇌ NH₄⁺ + OH⁻, menurut Brønsted–Lowry H₂O berperan sebagai …', o: ['asam, karena memberi H⁺ kepada NH₃', 'basa, karena menerima H⁺', 'asam Lewis, karena menerima elektron', 'bukan asam maupun basa'], a: 0, e: 'H₂O melepas H⁺ menjadi OH⁻ (basa konjugasi), jadi H₂O adalah asam. NH₃ menerima H⁺ sehingga menjadi basa.' },
  { id: 'kim5-09', t: 'kim5', lv: 2, src: 'pola', q: 'Pada reaksi BF₃ + NH₃ → F₃B–NH₃, BF₃ berperan sebagai …', o: ['asam Lewis karena menerima pasangan elektron', 'basa Lewis karena memberi pasangan elektron', 'asam Arrhenius karena melepas H⁺', 'basa Brønsted karena menerima H⁺'], a: 0, e: 'NH₃ memberikan pasangan elektron bebas ke B, sehingga BF₃ yang menerima pasangan elektron adalah asam Lewis.' },
  { id: 'kim5-10', t: 'kim5', lv: 1, src: 'pola', q: 'pH larutan H₂SO₄ 0,005 M adalah …', o: ['2', '3', '2,3', '1'], a: 0, e: '[H⁺] = 0,005 × 2 = 10⁻² M, jadi pH = 2.' },
  { id: 'kim5-11', t: 'kim5', lv: 1, src: 'pola', q: 'pH larutan Ba(OH)₂ 0,0005 M adalah …', o: ['11', '10', '3', '12'], a: 0, e: '[OH⁻] = 0,0005 × 2 = 10⁻³. pOH = 3, pH = 14 − 3 = 11.' },
  { id: 'kim5-12', t: 'kim5', lv: 2, src: 'pola', q: 'Asam lemah HA 0,1 M dengan Ka = 10⁻⁵ memiliki pH …', o: ['3', '1', '5', '4'], a: 0, e: '[H⁺] = √(Ka × M) = √(10⁻⁵ × 10⁻¹) = 10⁻³. pH = 3.' },
  { id: 'kim5-13', t: 'kim5', lv: 2, src: 'pola', q: 'Larutan NH₃ 0,1 M (Kb = 10⁻⁵) memiliki pH …', o: ['11', '3', '9', '13'], a: 0, e: '[OH⁻] = √(10⁻⁵ × 10⁻¹) = 10⁻³. pOH = 3, pH = 11.' },
  { id: 'kim5-14', t: 'kim5', lv: 2, src: 'pola', q: 'Larutan HCl dengan pH = 2 diencerkan 100 kali. pH larutan menjadi …', o: ['4', '3', '2,01', '0'], a: 0, e: '[H⁺] turun 100 kali dari 10⁻² menjadi 10⁻⁴ M, jadi pH = 4.' },
  { id: 'kim5-15', t: 'kim5', lv: 2, src: 'pola', q: 'Sebanyak 100 mL HCl 0,1 M dicampur 100 mL HCl 0,3 M. pH campuran adalah …', o: ['1 − log 2', '1', '2 − log 2', '2'], a: 0, e: '[H⁺] = (100×0,1 + 100×0,3) / 200 = 0,2 M = 2 × 10⁻¹. pH = 1 − log 2.' },
  { id: 'kim5-16', t: 'kim5', lv: 2, src: 'pola', q: 'Asam sulfat pekat 98% massa dengan massa jenis 1,8 g/mL (Mr = 98) memiliki molaritas …', o: ['18 M', '9 M', '1,8 M', '98 M'], a: 0, e: 'M = 10 × % × ρ / Mr = 10 × 98 × 1,8 / 98 = 18 M.' },
  { id: 'kim5-17', t: 'kim5', lv: 2, src: 'pola', q: 'Asam asetat 0,1 M terionisasi 1%. Nilai Ka asam asetat adalah …', o: ['1 × 10⁻⁵', '1 × 10⁻³', '1 × 10⁻⁴', '1 × 10⁻⁷'], a: 0, e: 'Ka = α² × M = (10⁻²)² × 10⁻¹ = 10⁻⁵.' },
  { id: 'kim5-18', t: 'kim5', lv: 1, src: 'pola', q: 'Dari larutan 0,1 M berikut, yang tidak menghantarkan arus listrik adalah …', o: ['glukosa', 'HCl', 'NaCl', 'CH₃COOH'], a: 0, e: 'Glukosa adalah nonelektrolit: tidak terionisasi dalam air. HCl dan NaCl elektrolit kuat, CH₃COOH elektrolit lemah.' },
  { id: 'kim5-19', t: 'kim5', lv: 2, src: 'pola', q: 'Jika Ka asam HA = 1 × 10⁻⁵, maka Kb basa konjugasinya A⁻ (Kw = 10⁻¹⁴) adalah …', o: ['1 × 10⁻⁹', '1 × 10⁻⁵', '1 × 10⁻¹⁹', '1 × 10⁻²'], a: 0, e: 'Ka × Kb = Kw, jadi Kb = 10⁻¹⁴ / 10⁻⁵ = 10⁻⁹.' },

  /* kim6 */
  { id: 'kim6-01', t: 'kim6', lv: 1, src: 'pola', q: 'Larutan garam berikut yang memiliki pH = 7 adalah …', o: ['KNO₃', 'CH₃COOK', 'NH₄Cl', 'Na₂CO₃'], a: 0, e: 'KNO₃ berasal dari basa kuat (KOH) dan asam kuat (HNO₃), tidak terhidrolisis. Tiga lainnya mengandung ion asam lemah atau basa lemah.' },
  { id: 'kim6-02', t: 'kim6', lv: 1, src: 'pola', q: 'Larutan NH₄Cl bersifat asam karena …', o: ['ion NH₄⁺ terhidrolisis menghasilkan H⁺', 'ion Cl⁻ terhidrolisis menghasilkan H⁺', 'NH₄Cl terionisasi menghasilkan OH⁻', 'ion NH₄⁺ dan Cl⁻ sama-sama terhidrolisis'], a: 0, e: 'NH₄⁺ berasal dari basa lemah dan bereaksi dengan air: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺. Cl⁻ berasal dari asam kuat sehingga tidak terhidrolisis.' },
  { id: 'kim6-03', t: 'kim6', lv: 2, src: 'pola', q: 'Larutan CH₃COONa 0,1 M (Ka CH₃COOH = 10⁻⁵) memiliki pH …', o: ['9', '5', '8', '13'], a: 0, e: '[OH⁻] = √(Kw/Ka × M) = √(10⁻⁹ × 10⁻¹) = 10⁻⁵. pOH = 5, pH = 9.' },
  { id: 'kim6-04', t: 'kim6', lv: 2, src: 'pola', q: 'Larutan NH₄Cl 0,1 M (Kb NH₃ = 10⁻⁵) memiliki pH …', o: ['5', '9', '6', '1'], a: 0, e: '[H⁺] = √(Kw/Kb × M) = √(10⁻⁹ × 10⁻¹) = 10⁻⁵. pH = 5.' },
  { id: 'kim6-05', t: 'kim6', lv: 2, src: 'pola', q: 'Sebanyak 100 mL HCl 0,3 M dicampur 100 mL NaOH 0,1 M. pH campuran adalah …', o: ['1', '2', '7', '13'], a: 0, e: 'H⁺ = 30 mmol, OH⁻ = 10 mmol. Sisa H⁺ = 20 mmol dalam 200 mL = 0,1 M. pH = 1.' },
  { id: 'kim6-06', t: 'kim6', lv: 2, src: 'pola', q: 'Sebanyak 100 mL CH₃COOH 0,2 M dicampur 50 mL NaOH 0,2 M (Ka = 10⁻⁵). pH campuran adalah …', o: ['5', '9', '3', '7'], a: 0, e: 'Mol asam 20 mmol, NaOH 10 mmol. Sisa asam 10 mmol dan garam 10 mmol: penyangga. [H⁺] = 10⁻⁵ × 10/10, pH = 5.' },
  { id: 'kim6-07', t: 'kim6', lv: 3, src: 'pola', q: 'Sebanyak 100 mL NaOH 0,2 M dicampur 100 mL HCN 0,2 M (Ka HCN = 10⁻⁹). pH campuran adalah …', o: ['11', '3', '9', '13'], a: 0, e: 'Habis tepat membentuk NaCN 20 mmol dalam 200 mL = 0,1 M. [OH⁻] = √(10⁻⁵ × 10⁻¹) = 10⁻³. pOH = 3, pH = 11.' },
  { id: 'kim6-08', t: 'kim6', lv: 3, src: 'pola', q: 'Larutan garam NaA 0,01 M memiliki pH = 10. Nilai Ka asam HA adalah …', o: ['1 × 10⁻⁸', '1 × 10⁻⁶', '1 × 10⁻⁴', '1 × 10⁻¹⁰'], a: 0, e: 'pOH = 4, [OH⁻] = 10⁻⁴. [OH⁻]² = Kw/Ka × M → 10⁻⁸ = (10⁻¹⁴/Ka) × 10⁻², jadi Kw/Ka = 10⁻⁶ dan Ka = 10⁻⁸.' },
  { id: 'kim6-09', t: 'kim6', lv: 2, src: 'pola', q: 'Larutan garam CH₃COONH₄ dibuat dari asam dengan Ka = 2 × 10⁻⁵ dan basa dengan Kb = 1 × 10⁻⁵. Larutan tersebut bersifat …', o: ['asam, karena Ka > Kb', 'basa, karena Ka > Kb', 'netral, karena garam dari asam dan basa lemah', 'asam, karena Ka < Kb'], a: 0, e: 'Pada hidrolisis sempurna, jika Ka > Kb maka larutan bersifat asam.' },
  { id: 'kim6-10', t: 'kim6', lv: 2, src: 'pola', q: 'Campuran berikut yang membentuk larutan penyangga adalah …', o: ['100 mL NH₃ 0,2 M + 50 mL HCl 0,2 M', '100 mL NH₃ 0,2 M + 100 mL HCl 0,2 M', '100 mL HCl 0,1 M + 100 mL NaOH 0,1 M', '100 mL NaOH 0,2 M + 50 mL HCl 0,1 M'], a: 0, e: 'Penyangga butuh basa/asam lemah bersisa bersama garamnya. Pilihan pertama: NH₃ sisa 10 mmol dan NH₄Cl 10 mmol. Pilihan kedua habis tepat (hidrolisis), ketiga netral, keempat sisa basa kuat.' },
  { id: 'kim6-11', t: 'kim6', lv: 2, src: 'pola', q: 'Sebanyak 100 mL NH₃ 0,2 M dicampur 50 mL HCl 0,2 M (Kb = 10⁻⁵). pH campuran adalah …', o: ['9', '5', '11', '7'], a: 0, e: 'NH₃ sisa 10 mmol, NH₄⁺ terbentuk 10 mmol. [OH⁻] = Kb × 10/10 = 10⁻⁵. pOH = 5, pH = 9.' },
  { id: 'kim6-12', t: 'kim6', lv: 2, src: 'pola', q: 'Persamaan hidrolisis yang benar untuk larutan Na₂CO₃ adalah …', o: ['CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻', 'Na⁺ + H₂O ⇌ NaOH + H⁺', 'CO₃²⁻ + H₂O ⇌ H₂CO₃ + 2OH⁻', 'Na⁺ + CO₃²⁻ → Na₂CO₃'], a: 0, e: 'Hanya CO₃²⁻ (dari asam lemah) yang terhidrolisis dan menghasilkan OH⁻, sehingga larutan basa. Na⁺ tidak terhidrolisis.' },

  /* kim17 */
  { id: 'kim17-01', t: 'kim17', lv: 2, src: 'pola', q: 'Sebanyak 20 mL H₂SO₄ dititrasi dengan NaOH 0,2 M dan butuh 30 mL NaOH. Molaritas H₂SO₄ adalah …', o: ['0,15 M', '0,3 M', '0,075 M', '0,6 M'], a: 0, e: 'Va × Ma × 2 = Vb × Mb × 1 → 20 × Ma × 2 = 30 × 0,2 → Ma = 6 / 40 = 0,15 M.' },
  { id: 'kim17-02', t: 'kim17', lv: 1, src: 'pola', q: 'Tiga kali titrasi 10 mL HCl dengan NaOH 0,1 M membutuhkan NaOH 10,1 mL, 9,9 mL, dan 10,0 mL. Molaritas HCl adalah …', o: ['0,1 M', '0,101 M', '0,099 M', '1 M'], a: 0, e: 'Volume rata-rata NaOH = 10,0 mL. 10 × Ma = 10,0 × 0,1 → Ma = 0,1 M.' },
  { id: 'kim17-03', t: 'kim17', lv: 2, src: 'pola', q: 'Indikator yang paling tepat untuk titrasi CH₃COOH dengan NaOH adalah …', o: ['fenolftalein (8,3–10,0)', 'metil jingga (3,1–4,4)', 'metil merah (4,2–6,3)', 'timol hijau (1,2–2,8)'], a: 0, e: 'Garam CH₃COONa bersifat basa, pH ekivalen > 7. Trayek fenolftalein mencakup pH itu.' },
  { id: 'kim17-04', t: 'kim17', lv: 2, src: 'pola', q: 'Indikator yang cocok untuk titrasi NH₃ dengan HCl adalah …', o: ['metil merah (4,2–6,3)', 'fenolftalein (8,3–10,0)', 'alizarin kuning (10,1–12,0)', 'kresol merah (7,2–8,8)'], a: 0, e: 'Garam NH₄Cl bersifat asam, pH ekivalen < 7, sehingga dipilih indikator dengan trayek di daerah asam.' },
  { id: 'kim17-05', t: 'kim17', lv: 1, src: 'pola', q: 'Pada titrasi HCl dengan NaOH, pH larutan di titik ekivalen adalah …', o: ['7', 'lebih dari 7', 'kurang dari 7', '14'], a: 0, e: 'Hasilnya NaCl yang tidak terhidrolisis, jadi pH = 7.' },
  { id: 'kim17-06', t: 'kim17', lv: 3, src: 'pola', q: 'Sebanyak 50 mL CH₃COOH 0,2 M dititrasi NaOH 0,2 M (Ka = 10⁻⁵). pH di titik ekivalen adalah …', o: ['9', '5', '7', '11'], a: 0, e: 'Ekivalen saat NaOH 50 mL. Garam 10 mmol / 100 mL = 0,1 M. [OH⁻] = √(10⁻⁹ × 10⁻¹) = 10⁻⁵. pH = 9.' },
  { id: 'kim17-07', t: 'kim17', lv: 3, src: 'pola', q: 'Sebanyak 25 mL asam lemah HA 0,1 M dititrasi NaOH 0,1 M. Setelah ditambah 12,5 mL NaOH, pH = 5. Nilai Ka HA adalah …', o: ['1 × 10⁻⁵', '1 × 10⁻⁹', '2 × 10⁻⁵', '1 × 10⁻¹'], a: 0, e: '12,5 mL adalah setengah volume ekivalen (25 mL), sehingga [HA] = [A⁻] dan pH = pKa = 5. Ka = 10⁻⁵.' },
  { id: 'kim17-08', t: 'kim17', lv: 3, src: 'pola', q: 'Sebanyak 10 mL cuka diencerkan menjadi 100 mL. Larutan encer sebanyak 25 mL dititrasi dengan NaOH 0,1 M dan butuh 20 mL. Molaritas CH₃COOH dalam cuka awal adalah …', o: ['0,8 M', '0,08 M', '0,2 M', '8 M'], a: 0, e: 'Cuka encer: 25 × M = 20 × 0,1 → M = 0,08 M. Awal diencerkan 10 kali, jadi 0,08 × 10 = 0,8 M.' },
  { id: 'kim17-09', t: 'kim17', lv: 1, src: 'pola', q: 'Titik akhir titrasi adalah saat …', o: ['indikator berubah warna', 'pH larutan tepat 7', 'volume titran sebanyak volume analit', 'seluruh titran habis'], a: 0, e: 'Titik akhir ditandai perubahan warna indikator, dipilih agar dekat dengan titik ekivalen (mol H⁺ = mol OH⁻).' },
  { id: 'kim17-10', t: 'kim17', lv: 2, src: 'pola', q: 'Pada titrasi iodometri, titik akhir ditandai dengan …', o: ['hilangnya warna biru kompleks amilum–iodin', 'munculnya warna merah muda', 'warna kuning berubah menjadi hijau', 'terbentuknya endapan putih'], a: 0, e: 'I₂ yang dibebaskan dititrasi dengan tiosulfat. Amilum membuat larutan biru tua, dan titik akhir saat warna biru hilang karena I₂ habis.' },
  { id: 'kim17-11', t: 'kim17', lv: 2, src: 'pola', q: 'Dibandingkan titrasi asam kuat–basa kuat, titrasi asam lemah dengan basa kuat memiliki …', o: ['pH awal lebih tinggi dan pH titik ekivalen lebih dari 7', 'pH awal lebih rendah dan pH titik ekivalen sama dengan 7', 'pH titik ekivalen kurang dari 7', 'tidak ada daerah penyangga'], a: 0, e: 'Asam lemah terionisasi sebagian sehingga pH awal lebih tinggi. Garam hasil bersifat basa sehingga pH ekivalen > 7, dan ada daerah penyangga sebelum ekivalen.' }
  ,
  /* kim13 redoks */
  { id: 'kim13-01', t: 'kim13', lv: 1, src: 'pola', q: 'Bilangan oksidasi Mn dalam KMnO₄ adalah …', o: ['+7', '+4', '+6', '+2'], a: 0, e: 'K = +1, O = −2 × 4 = −8. Jumlah harus 0: +1 + Mn − 8 = 0, jadi Mn = +7.' },
  { id: 'kim13-02', t: 'kim13', lv: 1, src: 'pola', q: 'Bilangan oksidasi Cr dalam ion Cr₂O₇²⁻ adalah …', o: ['+6', '+3', '+7', '+12'], a: 0, e: '2Cr + 7(−2) = −2, jadi 2Cr = +12 dan Cr = +6.' },
  { id: 'kim13-03', t: 'kim13', lv: 2, src: 'pola', q: 'Bilangan oksidasi N dalam ion NH₄⁺ adalah …', o: ['−3', '+3', '−4', '+5'], a: 0, e: 'N + 4(+1) = +1, jadi N = −3.' },
  { id: 'kim13-04', t: 'kim13', lv: 2, src: 'pola', q: 'Bilangan oksidasi atom O pada H₂O₂ dan OF₂ berturut-turut adalah …', o: ['−1 dan +2', '−2 dan −2', '−1 dan −2', '−2 dan +2'], a: 0, e: 'H₂O₂ adalah peroksida (O = −1). Pada OF₂, F lebih elektronegatif sehingga F = −1 dan O = +2.' },
  { id: 'kim13-05', t: 'kim13', lv: 1, src: 'pola', q: 'Pada reaksi Zn + 2HCl → ZnCl₂ + H₂, yang bertindak sebagai oksidator adalah …', o: ['HCl', 'Zn', 'ZnCl₂', 'H₂'], a: 0, e: 'H pada HCl turun dari +1 ke 0 (reduksi), jadi HCl adalah oksidator. Zn naik dari 0 ke +2 sehingga Zn adalah reduktor.' },
  { id: 'kim13-06', t: 'kim13', lv: 1, src: 'pola', q: 'Reaksi berikut yang BUKAN reaksi redoks adalah …', o: ['NaOH + HCl → NaCl + H₂O', 'CuO + H₂ → Cu + H₂O', '2Na + Cl₂ → 2NaCl', 'Zn + CuSO₄ → ZnSO₄ + Cu'], a: 0, e: 'Pada penetralan, biloks semua atom tidak berubah. Tiga reaksi lain melibatkan unsur bebas dan berubahnya biloks.' },
  { id: 'kim13-07', t: 'kim13', lv: 2, src: 'pola', q: 'Reaksi yang termasuk autoredoks (disproporsionasi) adalah …', o: ['Cl₂ + 2OH⁻ → Cl⁻ + ClO⁻ + H₂O', 'Zn + Cu²⁺ → Zn²⁺ + Cu', '2H₂ + O₂ → 2H₂O', 'CaCO₃ → CaO + CO₂'], a: 0, e: 'Cl dalam Cl₂ (0) menjadi Cl⁻ (−1, reduksi) dan ClO⁻ (+1, oksidasi): satu zat sekaligus dioksidasi dan direduksi.' },
  { id: 'kim13-08', t: 'kim13', lv: 3, src: 'pola', q: 'Setelah disetarakan, reaksi MnO₄⁻ + C₂O₄²⁻ + H⁺ → Mn²⁺ + CO₂ + H₂O memiliki koefisien C₂O₄²⁻ sebesar …', o: ['5', '2', '3', '10'], a: 0, e: 'Mn turun 5, C₂ naik 2. KPK 10: MnO₄⁻ = 2, C₂O₄²⁻ = 5. Hasil 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O.' },
  { id: 'kim13-09', t: 'kim13', lv: 2, src: 'pola', q: 'Jumlah mol elektron yang diterima 0,1 mol MnO₄⁻ yang berubah menjadi Mn²⁺ adalah …', o: ['0,5 mol', '0,1 mol', '0,2 mol', '0,7 mol'], a: 0, e: 'Biloks Mn turun dari +7 ke +2 (5 satuan). Mol elektron = 0,1 × 5 = 0,5 mol.' },
  { id: 'kim13-10', t: 'kim13', lv: 3, src: 'pola', q: 'Pada reaksi Cu + HNO₃ → Cu(NO₃)₂ + NO + H₂O (setara), koefisien HNO₃ adalah …', o: ['8', '4', '6', '2'], a: 0, e: '3Cu + 8HNO₃ → 3Cu(NO₃)₂ + 2NO + 4H₂O. Cu naik 2 (× 3 = 6), N turun 3 (× 2 = 6). N: 8 = 6 + 2.' },
  { id: 'kim13-11', t: 'kim13', lv: 3, src: 'pola', q: 'Reaksi yang merupakan konproporsionasi (hasil oksidasi dan reduksi berupa zat yang sama) adalah …', o: ['2H₂S + SO₂ → 3S + 2H₂O', 'Cl₂ + 2OH⁻ → Cl⁻ + ClO⁻ + H₂O', '2KClO₃ → 2KCl + 3O₂', 'Fe + 2HCl → FeCl₂ + H₂'], a: 0, e: 'S dalam H₂S (−2) dan SO₂ (+4) sama-sama menjadi S (0). Pilihan kedua adalah disproporsionasi, bukan konproporsionasi.' },

  /* kim18 penyangga */
  { id: 'kim18-01', t: 'kim18', lv: 1, src: 'pola', q: 'Pasangan yang membentuk larutan penyangga adalah …', o: ['CH₃COOH dan CH₃COONa', 'HCl dan NaCl', 'NaOH dan NaCl', 'HNO₃ dan NaNO₃'], a: 0, e: 'Penyangga butuh asam atau basa lemah bersama konjugasinya. CH₃COOH adalah asam lemah dan CH₃COO⁻ basa konjugasinya.' },
  { id: 'kim18-02', t: 'kim18', lv: 1, src: 'pola', q: 'Sebanyak 100 mL CH₃COOH 0,1 M dicampur 100 mL CH₃COONa 0,1 M (Ka = 10⁻⁵). pH campuran adalah …', o: ['5', '3', '9', '7'], a: 0, e: 'Mol asam = mol garam = 10 mmol. [H⁺] = Ka × 10/10 = 10⁻⁵, jadi pH = 5 (pH = pKa).' },
  { id: 'kim18-03', t: 'kim18', lv: 2, src: 'pola', q: 'Sebanyak 100 mL NH₃ 0,3 M dicampur 100 mL NH₄Cl 0,15 M (Kb = 10⁻⁵). pH campuran adalah …', o: ['9 + log 2', '5 − log 2', '9 − log 2', '5 + log 2'], a: 0, e: 'Mol NH₃ 30 mmol, NH₄⁺ 15 mmol. [OH⁻] = 10⁻⁵ × 30/15 = 2 × 10⁻⁵. pOH = 5 − log 2, pH = 9 + log 2.' },
  { id: 'kim18-04', t: 'kim18', lv: 2, src: 'pola', q: 'Sebanyak 100 mL CH₃COOH 0,3 M dicampur 100 mL NaOH 0,1 M (Ka = 10⁻⁵). pH campuran adalah …', o: ['5 − log 2', '5 + log 2', '9', '3'], a: 0, e: 'Asam 30 mmol, NaOH 10 mmol. Sisa asam 20 mmol, garam 10 mmol: penyangga. [H⁺] = 10⁻⁵ × 20/10 = 2 × 10⁻⁵. pH = 5 − log 2.' },
  { id: 'kim18-05', t: 'kim18', lv: 3, src: 'pola', q: 'Sebanyak 100 mL CH₃COOH 0,1 M dicampur 100 mL (CH₃COO)₂Ca 0,05 M (Ka = 10⁻⁵). pH campuran adalah …', o: ['6 − log 5', '5 − log 5', '5', '6'], a: 0, e: 'Mol asam 10 mmol. Garam 10 mmol memberi 20 mmol CH₃COO⁻ (a = 2). [H⁺] = 10⁻⁵ × 10/20 = 5 × 10⁻⁶. pH = 6 − log 5.' },
  { id: 'kim18-06', t: 'kim18', lv: 3, src: 'pola', q: 'Penyangga 0,2 mol CH₃COOH dan 0,2 mol CH₃COONa (Ka = 10⁻⁵, pH = 5) ditambah 0,02 mol HCl (volume tidak berubah). pH menjadi sekitar …', o: ['4,9', '5,1', '3', '7'], a: 0, e: 'H⁺ bereaksi dengan CH₃COO⁻: asam 0,22 mol, garam 0,18 mol. [H⁺] = 10⁻⁵ × 0,22/0,18 = 1,22 × 10⁻⁵, pH ≈ 4,9.' },
  { id: 'kim18-07', t: 'kim18', lv: 1, src: 'pola', q: 'Jika larutan penyangga diencerkan 10 kali, pH-nya …', o: ['hampir tidak berubah', 'naik 1 satuan', 'turun 1 satuan', 'menjadi 7'], a: 0, e: 'Mol asam lemah dan mol konjugat tetap, perbandingannya tidak berubah, sehingga pH hampir tetap.' },
  { id: 'kim18-08', t: 'kim18', lv: 1, src: 'pola', q: 'Sistem penyangga utama yang menjaga pH darah adalah …', o: ['H₂CO₃ / HCO₃⁻', 'HCl / Cl⁻', 'NaOH / Na⁺', 'CH₃COOH / CH₃COO⁻'], a: 0, e: 'Darah memakai pasangan asam karbonat dan bikarbonat sehingga pH tetap sekitar 7,4.' },
  { id: 'kim18-09', t: 'kim18', lv: 3, src: 'pola', q: 'Perbandingan mol CH₃COOH : CH₃COO⁻ yang diperlukan untuk membuat penyangga pH = 6 (Ka = 10⁻⁵) adalah …', o: ['1 : 10', '10 : 1', '1 : 1', '1 : 100'], a: 0, e: '[H⁺] = 10⁻⁶ = 10⁻⁵ × (asam / garam), jadi asam / garam = 0,1 = 1 : 10.' },
  { id: 'kim18-10', t: 'kim18', lv: 2, src: 'pola', q: 'Perbandingan mol NH₃ : NH₄Cl agar penyangga pH = 9 (Kb NH₃ = 10⁻⁵) adalah …', o: ['1 : 1', '1 : 10', '10 : 1', '1 : 100'], a: 0, e: 'pH 9 berarti pOH 5, [OH⁻] = 10⁻⁵ = Kb × (basa / garam), jadi basa / garam = 1.' },
  { id: 'kim18-11', t: 'kim18', lv: 2, src: 'pola', q: 'Ke dalam penyangga NH₃/NH₄Cl ditambahkan sedikit NaOH. Reaksi yang menjaga pH adalah …', o: ['NH₄⁺ + OH⁻ → NH₃ + H₂O', 'NH₃ + OH⁻ → NH₂⁻ + H₂O', 'NH₃ + H⁺ → NH₄⁺', 'Cl⁻ + OH⁻ → ClO⁻ + H⁻'], a: 0, e: 'Komponen asam (NH₄⁺) menetralkan OH⁻ yang ditambahkan sehingga [OH⁻] hampir tidak berubah.' },

  /* kim7 Ksp */
  { id: 'kim7-01', t: 'kim7', lv: 1, src: 'pola', q: 'Ungkapan Ksp untuk Ag₂CrO₄ adalah …', o: ['[Ag⁺]²[CrO₄²⁻]', '[Ag⁺][CrO₄²⁻]', '[Ag⁺]²[CrO₄²⁻]²', '[Ag₂CrO₄]'], a: 0, e: 'Ag₂CrO₄ ⇌ 2Ag⁺ + CrO₄²⁻. Ksp = [Ag⁺]² [CrO₄²⁻]. Padatan tidak ditulis.' },
  { id: 'kim7-02', t: 'kim7', lv: 1, src: 'pola', q: 'Ksp AgCl = 1 × 10⁻¹⁰. Kelarutan AgCl dalam air adalah …', o: ['1 × 10⁻⁵ M', '1 × 10⁻¹⁰ M', '2 × 10⁻⁵ M', '1 × 10⁻² M'], a: 0, e: 'Tipe AB: Ksp = s². s = √10⁻¹⁰ = 10⁻⁵ M.' },
  { id: 'kim7-03', t: 'kim7', lv: 2, src: 'pola', q: 'Ksp Mg(OH)₂ = 4 × 10⁻¹². Kelarutan Mg(OH)₂ dalam air adalah …', o: ['1 × 10⁻⁴ M', '2 × 10⁻⁶ M', '1 × 10⁻⁶ M', '4 × 10⁻⁴ M'], a: 0, e: 'Ksp = 4s³ → s³ = 10⁻¹² → s = 10⁻⁴ M.' },
  { id: 'kim7-04', t: 'kim7', lv: 2, src: 'pola', q: 'Kelarutan Ca(OH)₂ dalam air 2 × 10⁻² M. Nilai Ksp Ca(OH)₂ adalah …', o: ['3,2 × 10⁻⁵', '8 × 10⁻⁶', '1,6 × 10⁻⁵', '4 × 10⁻⁴'], a: 0, e: 'Ksp = 4s³ = 4 × (2 × 10⁻²)³ = 4 × 8 × 10⁻⁶ = 3,2 × 10⁻⁵.' },
  { id: 'kim7-05', t: 'kim7', lv: 3, src: 'pola', q: 'Dalam 1 L larutan jenuh Mg(OH)₂ terlarut 5,8 mg (Mr = 58). Nilai Ksp Mg(OH)₂ adalah …', o: ['4 × 10⁻¹²', '1 × 10⁻⁸', '1 × 10⁻¹²', '2 × 10⁻⁸'], a: 0, e: 's = (5,8 × 10⁻³ g / 58) / 1 L = 10⁻⁴ M. Ksp = 4s³ = 4 × 10⁻¹².' },
  { id: 'kim7-06', t: 'kim7', lv: 2, src: 'pola', q: 'Kelarutan AgCl (Ksp = 10⁻¹⁰) dalam larutan NaCl 0,1 M adalah …', o: ['1 × 10⁻⁹ M', '1 × 10⁻⁵ M', '1 × 10⁻¹¹ M', '1 × 10⁻¹⁰ M'], a: 0, e: '[Cl⁻] ≈ 0,1 M dari NaCl. [Ag⁺] = 10⁻¹⁰ / 10⁻¹ = 10⁻⁹. Ion senama memperkecil kelarutan.' },
  { id: 'kim7-07', t: 'kim7', lv: 1, src: 'pola', q: 'Ksp AgCl = 10⁻¹⁰, AgBr = 5 × 10⁻¹³, AgI = 10⁻¹⁶. Garam yang paling sukar larut dalam air adalah …', o: ['AgI', 'AgBr', 'AgCl', 'ketiganya sama'], a: 0, e: 'Ketiganya bertipe AB, jadi Ksp yang paling kecil berarti kelarutan paling kecil, yaitu AgI.' },
  { id: 'kim7-08', t: 'kim7', lv: 2, src: 'pola', q: 'Sebanyak 100 mL AgNO₃ 2 × 10⁻⁴ M dicampur 100 mL NaCl 2 × 10⁻⁴ M. Ksp AgCl = 10⁻¹⁰. Pernyataan yang tepat adalah …', o: ['Qsp = 10⁻⁸ > Ksp sehingga terbentuk endapan', 'Qsp = 4 × 10⁻⁸ < Ksp sehingga tidak mengendap', 'Qsp = Ksp sehingga larutan tepat jenuh', 'Qsp = 10⁻¹² sehingga tidak mengendap'], a: 0, e: 'Setelah dicampur volume 200 mL: [Ag⁺] = [Cl⁻] = 10⁻⁴ M. Qsp = 10⁻⁸ jauh di atas Ksp, maka AgCl mengendap.' },
  { id: 'kim7-09', t: 'kim7', lv: 3, src: 'pola', q: 'Larutan Mg²⁺ 0,01 M ditambah basa. Jika Ksp Mg(OH)₂ = 4 × 10⁻¹², Mg(OH)₂ mulai mengendap pada pH …', o: ['9 + log 2', '5 − log 2', '9', '10'], a: 0, e: '[OH⁻]² = Ksp / [Mg²⁺] = 4 × 10⁻¹⁰, [OH⁻] = 2 × 10⁻⁵. pOH = 5 − log 2, pH = 9 + log 2.' },
  { id: 'kim7-10', t: 'kim7', lv: 2, src: 'pola', q: 'Kelarutan Mg(OH)₂ akan bertambah besar jika larutan …', o: ['ditambah asam (pH diturunkan)', 'ditambah NaOH', 'ditambah MgCl₂', 'dibuat bersuhu lebih rendah'], a: 0, e: 'Asam menetralkan OH⁻ sehingga kesetimbangan bergeser ke kanan dan lebih banyak Mg(OH)₂ larut. NaOH dan MgCl₂ adalah ion senama.' },
  { id: 'kim7-11', t: 'kim7', lv: 2, src: 'pola', q: 'Larutan mengandung Cl⁻ dan I⁻ dengan konsentrasi sama. AgNO₃ diteteskan sedikit demi sedikit (Ksp AgCl = 10⁻¹⁰, AgI = 10⁻¹⁶). Endapan yang terbentuk lebih dulu adalah …', o: ['AgI', 'AgCl', 'keduanya bersamaan', 'tidak ada yang mengendap'], a: 0, e: 'Ksp AgI lebih kecil, jadi Qsp-nya lebih cepat melampaui Ksp pada [Ag⁺] yang lebih rendah.' },
  { id: 'kim7-12', t: 'kim7', lv: 2, src: 'pola', q: 'Endapan AgCl dapat larut dalam larutan NH₃ karena …', o: ['terbentuk ion kompleks [Ag(NH₃)₂]⁺ yang larut', 'NH₃ bersifat asam kuat', 'NH₃ ion senama dengan AgCl', 'Ksp AgCl naik karena NH₃ memanaskan larutan'], a: 0, e: 'NH₃ mengikat Ag⁺ membentuk ion kompleks, sehingga [Ag⁺] turun dan kesetimbangan bergeser ke arah larutnya AgCl.' }
];
